assert.ok(canonicalBridgeMatch,'Production canonical URL normalizer must be extractable for behavioral tests');
assert.ok(bridgeMatch,'Search archive bridge implementation must be extractable for behavioral tests');
const bridgeSandbox={
 localStorage:{data:new Map(),getItem(key){return this.data.has(key)?this.data.get(key):null;},setItem(key,value){this.data.set(key,String(value));}},
 Date,Math,URL,
 localArchiveKey:(userId)=>{if(typeof userId!=='string'||!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(userId))throw new Error('Profilo non valido per archivio locale.');return 'nextway_ai_records_v1:'+userId;},
 safeHttpUrl:(value)=>{try{const url=new URL(String(value||''));return ['http:','https:'].includes(url.protocol)&&!url.username&&!url.password?url.href:'';}catch{return '';}},
 readSearchArchiveRows(userId){try{const rows=JSON.parse(this.localStorage.getItem(this.localArchiveKey(userId))||'[]');return Array.isArray(rows)?rows:[];}catch{return [];}},
 readSearchArchiveMeta(lead){const notes=String(lead?.notes||''),marker='[NEXTWAY_PROSPECT_METADATA_V1]',at=notes.lastIndexOf(marker);if(at<0)return {};try{return JSON.parse(notes.slice(at+marker.length).trim())||{};}catch{return {};}}
};
vm.runInNewContext(canonicalBridgeMatch[0]+'\n'+bridgeMatch[0]+';this.addSearchLeadToLocalArchive=addSearchLeadToLocalArchive;',bridgeSandbox);
const bridgeOwner='123e4567-e89b-42d3-a456-426614174000';
const bridgeRecord={title:'Andrea Fabbri · Nutrizionista',url:'https://www.linkedin.com/in/andrea-fabbri-8039157b/?utm_source=test#bio',evidence:'Profilo professionale pubblico · nutrizionista · Roma',identity_keys:['linkedin:andrea-fabbri-8039157b'],evidence_quality:{prospect_profile:{name:'Andrea Fabbri',profession:'Nutrizionista',location:'Roma'}}};
const bridgeSaved=bridgeSandbox.addSearchLeadToLocalArchive(bridgeOwner,bridgeRecord);
assert.equal(bridgeSaved.duplicate,false,'First manual acquisition must create one local archive lead');
assert.equal(bridgeSaved.lead.name,'Andrea Fabbri');
assert.equal(bridgeSaved.lead.profession,'Nutrizionista');
assert.equal(bridgeSandbox.readSearchArchiveRows(bridgeOwner).length,1,'Acquisition must persist exactly one lead in the authenticated owner archive');
assert.ok(bridgeSandbox.readSearchArchiveRows(bridgeOwner)[0].notes.includes('[NEXTWAY_PROSPECT_METADATA_V1]'),'Acquisition must preserve structured prospect metadata in the local archive');
assert.equal(bridgeSandbox.readSearchArchiveRows(bridgeOwner)[0].url,bridgeRecord.url,'Acquisition must preserve the original source URL');
assert.equal(bridgeSandbox.readSearchArchiveRows('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa').length,0,'Acquired leads must remain isolated by owner');
const bridgeDuplicate=bridgeSandbox.addSearchLeadToLocalArchive(bridgeOwner,{...bridgeRecord,url:'https://linkedin.com/in/andrea-fabbri-8039157b',identity_keys:[]});
assert.equal(bridgeDuplicate.duplicate,true,'Canonical URL matching must detect duplicates across www, tracking parameters, fragments and trailing slashes even without identity keys');
assert.equal(bridgeSandbox.readSearchArchiveRows(bridgeOwner).length,1,'Duplicate acquisition must not create a second lead');
const identityDuplicate=bridgeSandbox.addSearchLeadToLocalArchive(bridgeOwner,{...bridgeRecord,url:'https://example.org/another-public-page',identity_keys:['linkedin:andrea-fabbri-8039157b']});
assert.equal(identityDuplicate.duplicate,true,'Stable public identity keys must prevent duplicate acquisition across different source URLs');
assert.throws(()=>bridgeSandbox.addSearchLeadToLocalArchive('invalid-owner',bridgeRecord),/Profilo non valido/,'Archive acquisition must reject an invalid owner scope');
assert.throws(()=>bridgeSandbox.addSearchLeadToLocalArchive(bridgeOwner,{...bridgeRecord,url:'javascript:alert(1)'}),/URL della fonte non valido/,'Archive acquisition must reject unsafe source URLs');
assert.throws(()=>bridgeSandbox.addSearchLeadToLocalArchive(bridgeOwner,{...bridgeRecord,evidence:''}),/non contiene titolo o evidenza/,'Archive acquisition must reject records without public evidence');
assert.equal(bridgeSandbox.readSearchArchiveRows(bridgeOwner).length,1,'Rejected and duplicate acquisitions must not mutate the local archive');


const syntheticBridgeTest=bridgeSandbox.addSearchLeadToLocalArchive(bridgeOwner,{title:'TEST TECNICO NEXTWAY — NON È UN PROSPECT',url:'https://example.com/nextway-bridge-test',evidence:'Record sintetico esclusivamente tecnico.',is_test:true,evidence_quality:{prospect_profile:{name:'TEST TECNICO NEXTWAY'}}});
assert.equal(syntheticBridgeTest.duplicate,false,'The local bridge must allow a dedicated synthetic test record');
assert.equal(syntheticBridgeTest.lead.is_test,true,'Synthetic bridge records must carry the test-only marker');
const rowsWithTest=bridgeSandbox.readSearchArchiveRows(bridgeOwner);
assert.equal(rowsWithTest.length,2,'A synthetic test must be written to the same owner-scoped archive');
assert.equal(rowsWithTest.filter(row=>row.is_test).length,1,'Exactly one test record must be marked as technical');
const rowsAfterCleanup=rowsWithTest.filter(row=>!(row.id===syntheticBridgeTest.lead.id&&row.is_test===true));
bridgeSandbox.localStorage.setItem('nextway_ai_records_v1:'+bridgeOwner,JSON.stringify(rowsAfterCleanup));
assert.equal(bridgeSandbox.readSearchArchiveRows(bridgeOwner).length,1,'Removing the synthetic test must preserve all real archive rows');
assert.equal(bridgeSandbox.readSearchArchiveRows(bridgeOwner)[0].is_test,undefined,'Cleanup must leave the real lead unchanged');
assert.ok(searchHtml.includes('id="bridge-test-panel"'),'The search page must expose the controlled local bridge test');
assert.ok(searchHtml.includes('id="run-bridge-test"')&&searchHtml.includes('id="clean-bridge-test"'),'The local test must have explicit run and cleanup controls');
assert.ok(searchHtml.includes('removeBridgeTestRecord()'),'The UI must provide a dedicated cleanup operation');
assert.ok(archiveHtml.includes("x.is_test?' <span class=\"tag\">TEST TECNICO</span>':''"),'The archive must visibly label technical test records');
assert.ok(archiveHtml.includes('data.filter(x=>!x.is_test)'),'Technical test records must remain excluded from archive counters');

